def balanced(s):
    stack = []
    matching = {')': '(', ']': '[', '}': '{'}
    opening = set(matching.values())

    for char in s:
        if char in opening:
            stack.append(char)
        elif char in matching:
            if not stack:
                return False
            if stack[-1] != matching[char]:
                return False
            stack.pop()

    return not stack
